#include <stdio.h>

int main(void)
{
    int matrix[2][3] = {{1, 2, 3}, {4, 5, 6}};
    int (*row)[3] = matrix;
    row++;
    printf("%d %d\n", (*row)[0], row[0][2]);
    return 0;
}

#include <stdio.h>
#include <string.h>

int main(void)
{
    const char *names[] = {"A", "Campus", "Lab"};
    for (size_t i = 0; i < 3; i++) {
        printf("%s:%zu\n", names[i], strlen(names[i]));
    }
    return 0;
}

